class Agenthub < Formula
  desc "Local gateway between AI clients and MCP servers"
  homepage "https://github.com/dinstein/agent-hub"
  version "0.12.2"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.2/agenthub-0.12.2-4adf573-darwin-arm64.tar.gz"
      sha256 "cb31e2ffe94cb0ecae054a05c27f5eeab1102b4518f85db584ee1a03865584cf"
    end
    on_intel do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.2/agenthub-0.12.2-4adf573-darwin-amd64.tar.gz"
      sha256 "04e11a4fc06278cf1cc9671babe6e657ded3d6d468dbf51fc97a9aac42de9553"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.2/agenthub-0.12.2-4adf573-linux-arm64.tar.gz"
      sha256 "e6c94fbc2c38b1bf58fe9c155b049d1d13bd9dfd37b1a8ba610433462051d182"
    end
    on_intel do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.12.2/agenthub-0.12.2-4adf573-linux-amd64.tar.gz"
      sha256 "af2463e7054fc339b21af61d5c41913b17e37c8238a0e20f4983c5566c6e98e1"
    end
